import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.BEUshCVJ.js";const u=JSON.parse('{"title":"延迟探测","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/latency.md","filePath":"zh/guide/latency.md","lastUpdated":1793062321000}'),d={name:"zh/guide/latency.md"};function l(n,t,i,s,h,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="延迟探测" tabindex="-1">延迟探测 <a class="header-anchor" href="#延迟探测" aria-label="Permalink to &quot;延迟探测&quot;">​</a></h1><p>本页说明如何测量从你的网络访问各供应商的速度，以及 MeetCue 如何据此选择端点、比较不同组合。</p><h2 id="为什么要测" tabindex="-1">为什么要测 <a class="header-anchor" href="#为什么要测" aria-label="Permalink to &quot;为什么要测&quot;">​</a></h2><p>从问题结束到第一条要点出现的时间，取决于你的网络到各供应商的线路，而不只是供应商本身。很多供应商提供多个端点。MeetCue 不预设哪个适合你：它逐个测量，界面上只显示主机名和实测时间。</p><h2 id="运行探测" tabindex="-1">运行探测 <a class="header-anchor" href="#运行探测" aria-label="Permalink to &quot;运行探测&quot;">​</a></h2><ol><li>打开 <strong>设置 › 供应商与费用</strong>，点击 <strong>运行延迟探测</strong>。也可以点击面板底栏的延迟数字。</li><li>可选填 <strong>网络标签</strong>，例如“家”“办公室”，便于以后比较不同地点的结果。</li><li>没有 API 密钥时勾选 <strong>只测网络</strong>。这一项免费，会测量每个端点的 DNS、连接和 TLS 时间。</li><li>有密钥时，MeetCue 会先显示预计费用：每个语音识别服务约 30 秒音频、约 8 次简短的模型调用，合计几美分。点击 <strong>开始探测</strong> 确认。</li></ol><h2 id="测量内容" tabindex="-1">测量内容 <a class="header-anchor" href="#测量内容" aria-label="Permalink to &quot;测量内容&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>测量项</th><th>次数</th></tr></thead><tbody><tr><td>网络</td><td>每个端点的 DNS 解析、TCP 连接与 TLS 握手</td><td>5 次取中位数</td></tr><tr><td>语音识别</td><td>内置一段 9 秒的中英混说录音，以一个问题结尾，按实时速度推送。开口 → 第一个中间结果；音频结束 → 最终文本</td><td>3 次</td></tr><tr><td>模型</td><td>用要点提示词加一小段转写。请求 → 第一个 token；请求 → 第一条完整要点</td><td>热身 1 次后测 3 次</td></tr></tbody></table><h2 id="查看结果" tabindex="-1">查看结果 <a class="header-anchor" href="#查看结果" aria-label="Permalink to &quot;查看结果&quot;">​</a></h2><p>每个供应商一行，显示中位数和最慢值。<strong>组合</strong> 表估算每种识别与模型搭配的端到端延迟：</p><blockquote><p>句末等待 + 识别 + 检测 + 第一条要点</p></blockquote><p>以及每小时费用。可按最快、最省或均衡排序，然后在想要的组合上点击 <strong>应用</strong>。端点设为 <strong>自动</strong> 的供应商会切换到实测最快的端点。</p><h2 id="历史记录" tabindex="-1">历史记录 <a class="header-anchor" href="#历史记录" aria-label="Permalink to &quot;历史记录&quot;">​</a></h2><p>结果连同时间和网络标签保存在设置文件夹的 <code>latency-history.json</code> 中。练习模式用最近一次结果模拟识别延迟。</p><h2 id="实时监控" tabindex="-1">实时监控 <a class="header-anchor" href="#实时监控" aria-label="Permalink to &quot;实时监控&quot;">​</a></h2><p>会议中底栏显示最近一次提示的延迟，鼠标悬停显示中位数。连续三个问题超过 2.5 秒时，面板会建议重新探测：可能是网络变了，或最快的端点变了。</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>只有你自己的测量结果才有参考价值。在其他网络或云服务器上测出的延迟，说明不了你这里的情况。</p></div>',17)])])}const b=a(d,[["render",l]]);export{u as __pageData,b as default};
